1	// This file implements the organization-scoped audit chain. Every successful
2	// policy publish or rollback, and every Decide called with a non-empty
3	// decision organization, leaves an immutable record in that organization.
4	//
5	// Records carry an organization-local sequence starting at 1 and a SHA-256
6	// fingerprint that chains each record to the previous one. The genesis
7	// fingerprint binds the organization name, so records from another
8	// organization can never validate as part of this chain even when the
9	// sequence numbers and identifiers coincide.
10	package darksafe
11	
12	import (
13		"crypto/sha256"
14		"encoding/binary"
15		"encoding/hex"
16		"encoding/json"
17		"errors"
18		"fmt"
19		"unicode/utf8"
20	)
21	
22	// Audit record categories.
23	const (
24		// AuditPolicyChange is a successful publish or rollback.
25		AuditPolicyChange = "policy_change"
26		// AuditDecision is one Decide evaluation.
27		AuditDecision = "decision"
28	)
29	
30	// Sentinel errors for the audit entry points. Callers distinguish them
31	// with errors.Is; every one leaves state unchanged.
32	var (
33		// ErrInvalidPage means a page size or range argument was invalid.
34		ErrInvalidPage = errors.New("darksafe: invalid audit page")
35		// ErrInvalidRange means the upper bound is beyond what exists, the
36		// range is inverted, or a supplied fingerprint does not match.
37		ErrInvalidRange = errors.New("darksafe: invalid audit range")
38		// ErrAuditNotFound means no record exists at the requested sequence.
39		ErrAuditNotFound = errors.New("darksafe: audit record not found")
40		// ErrAuditNotADecision means the record at the sequence is not a
41		// decision record and therefore cannot be rechecked.
42		ErrAuditNotADecision = errors.New("darksafe: audit record is not a decision")
43	)
44	
45	// PolicyChange captures a successful publish or rollback.
46	type PolicyChange struct {
47		// Version is the newly created policy version.
48		Version int
49		// Policies is the full policy set of the new version.
50		Policies []Policy
51		// SourceVersion is the version copied by a rollback, and 0 for an
52		// ordinary publish.
53		SourceVersion int
54		// RolledBack reports whether the change was produced by Rollback.
55		RolledBack bool
56	}
57	
58	// DecisionRecord captures one Decide call: the full request and the
59	// decision actually returned.
60	type DecisionRecord struct {
61		Request  OrgRequest
62		Decision Decision
63	}
64	
65	// AuditRecord is one immutable entry in an organization's audit chain.
66	type AuditRecord struct {
67		Org      string
68		Seq      int // organization-local, starting at 1 and gapless
69		Kind     string
70		Change   *PolicyChange   // present when Kind == AuditPolicyChange
71		Decision *DecisionRecord // present when Kind == AuditDecision
72	
73		// PrevFingerprint is the fingerprint of the preceding record, or the
74		// genesis fingerprint for the first record.
75		PrevFingerprint string
76		// Fingerprint binds this record's full content to its predecessor.
77		Fingerprint string
78	}
79	
80	// hashEnvelope is the canonical, organization-bound representation that
81	// fingerprints are computed over. It is never exposed, so callers cannot
82	// forge one by constructing an AuditRecord with copied fields.
83	type hashEnvelope struct {
84		Org             string          `json:"org"`
85		Seq             int             `json:"seq"`
86		Kind            string          `json:"kind"`
87		Change          *PolicyChange   `json:"change,omitempty"`
88		Decision        *DecisionRecord `json:"decision,omitempty"`
89		PrevFingerprint string          `json:"prev"`
90	}
91	
92	// envelopeUsesRawBytes reports whether any string protected by the
93	// fingerprint carries bytes that are not valid UTF-8. Such envelopes are
94	// hashed through encodeCanonical instead of encoding/json, because JSON
95	// string encoding replaces invalid bytes with U+FFFD and would let two
96	// different raw contents share a fingerprint.
97	func envelopeUsesRawBytes(env *hashEnvelope) bool {
98		if !utf8.ValidString(env.Org) || !utf8.ValidString(env.Kind) ||
99			!utf8.ValidString(env.PrevFingerprint) {
100			return true
101		}
102		if env.Change != nil {
103			for _, p := range env.Change.Policies {
104				if !utf8.ValidString(p.ID) || !utf8.ValidString(p.Subject) ||
105					!utf8.ValidString(p.Action) || !utf8.ValidString(p.Scope) ||
106					!utf8.ValidString(string(p.Effect)) {
107					return true
108				}
109			}
110		}
111		if env.Decision != nil {
112			req := env.Decision.Request
113			d := env.Decision.Decision
114			for _, s := range []string{
115				req.SubjectOrg, req.ResourceOrg,
116				req.Subject.ID, req.Subject.Kind, req.Resource.ID, req.Resource.Scope,
117				req.Action, d.Reason,
118			} {
119				if !utf8.ValidString(s) {
120					return true
121				}
122			}
123			for _, s := range req.Subject.Roles {
124				if !utf8.ValidString(s) {
125					return true
126				}
127			}
128			for _, s := range d.Matched {
129				if !utf8.ValidString(s) {
130					return true
131				}
132			}
133		}
134		return false
135	}
136	
137	// rawEnvelopePrefix opens every raw-byte canonical encoding. It never
138	// coincides with the start of a JSON envelope (always '{'), so
139	// fingerprints from the two encodings live in collision-free spaces.
140	const rawEnvelopePrefix = "darksafe-audit-raw-v1\x00"
141	
142	// fingerprintTag delimits one field or nested value within the canonical
143	// binary encoding. Distinct tags keep two payloads that merely share
144	// adjacent bytes apart (e.g. ["ab",""] vs ["a","b"]).
145	type fingerprintTag byte
146	
147	const (
148		tagEnvelope fingerprintTag = iota + 1
149		tagSeq
150		tagString
151		tagStringList
152		tagBool
153		tagPolicy
154		tagPolicyList
155		tagChange
156		tagSubject
157		tagResource
158		tagDecision
159		tagDecisionRecord
160	)
161	
162	// fingerprintEncoder builds the canonical byte representation of an
163	// envelope. Unlike encoding/json it writes string contents byte-for-byte
164	// with an explicit length prefix, so strings carrying invalid UTF-8 stay
165	// distinguishable: encoding/json renders both a raw 0xFF byte and a raw
166	// 0xFE byte as the U+FFFD replacement rune, collapsing genuinely
167	// different content onto identical fingerprints.
168	type fingerprintEncoder struct {
169		buf []byte
170	}
171	
172	func (e *fingerprintEncoder) tag(t fingerprintTag) {
173		e.buf = append(e.buf, byte(t))
174	}
175	
176	func (e *fingerprintEncoder) int64Tag(t fingerprintTag, v int64) {
177		e.tag(t)
178		var b [8]byte
179		binary.BigEndian.PutUint64(b[:], uint64(v))
180		e.buf = append(e.buf, b[:]...)
181	}
182	
183	func (e *fingerprintEncoder) boolTag(t fingerprintTag, v bool) {
184		e.tag(t)
185		if v {
186			e.buf = append(e.buf, 1)
187		} else {
188			e.buf = append(e.buf, 0)
189		}
190	}
191	
192	// rawString tags and writes a string from its exact memory bytes. No
193	// validation, replacement or normalization is ever performed: an invalid
194	// UTF-8 byte reaches the hash unchanged.
195	func (e *fingerprintEncoder) rawString(s string) {
196		e.tag(tagString)
197		var b [4]byte
198		binary.BigEndian.PutUint32(b[:], uint32(len(s)))
199		e.buf = append(e.buf, b[:]...)
200		e.buf = append(e.buf, s...)
201	}
202	
203	// stringList preserves nil-vs-empty explicitly: in the JSON envelope a
204	// nil slice is "null" and a non-nil empty slice is "[]", so the raw
205	// encoding must keep the two shapes apart as well.
206	func (e *fingerprintEncoder) stringList(items []string) {
207		e.tag(tagStringList)
208		if items == nil {
209			e.buf = append(e.buf, 0)
210			return
211		}
212		e.buf = append(e.buf, 1)
213		var b [4]byte
214		binary.BigEndian.PutUint32(b[:], uint32(len(items)))
215		e.buf = append(e.buf, b[:]...)
216		for _, s := range items {
217			e.rawString(s)
218		}
219	}
220	
221	func (e *fingerprintEncoder) policy(p Policy) {
222		e.tag(tagPolicy)
223		e.rawString(p.ID)
224		e.rawString(p.Subject)
225		e.rawString(p.Action)
226		e.rawString(p.Scope)
227		e.rawString(string(p.Effect))
228		e.boolTag(tagBool, p.Recursive)
229	}
230	
231	func (e *fingerprintEncoder) policyList(policies []Policy) {
232		e.tag(tagPolicyList)
233		if policies == nil {
234			e.buf = append(e.buf, 0)
235			return
236		}
237		e.buf = append(e.buf, 1)
238		var b [4]byte
239		binary.BigEndian.PutUint32(b[:], uint32(len(policies)))
240		e.buf = append(e.buf, b[:]...)
241		for _, p := range policies {
242			e.policy(p)
243		}
244	}
245	
246	func (e *fingerprintEncoder) change(c *PolicyChange) {
247		e.tag(tagChange)
248		// A nil pointer is encoded as tagChange alone; a present value's
249		// fields follow immediately.
250		if c == nil {
251			return
252		}
253		e.int64Tag(tagSeq, int64(c.Version))
254		e.policyList(c.Policies)
255		e.int64Tag(tagSeq, int64(c.SourceVersion))
256		e.boolTag(tagBool, c.RolledBack)
257	}
258	
259	func (e *fingerprintEncoder) subject(su Subject) {
260		e.tag(tagSubject)
261		e.rawString(su.ID)
262		e.rawString(su.Kind)
263		e.stringList(su.Roles)
264		e.boolTag(tagBool, su.Disabled)
265	}
266	
267	func (e *fingerprintEncoder) resource(r Resource) {
268		e.tag(tagResource)
269		e.rawString(r.ID)
270		e.rawString(r.Scope)
271	}
272	
273	func (e *fingerprintEncoder) decision(d Decision) {
274		e.tag(tagDecision)
275		e.boolTag(tagBool, d.Allowed)
276		e.rawString(d.Reason)
277		e.stringList(d.Matched)
278		e.int64Tag(tagSeq, int64(d.Version))
279	}
280	
281	func (e *fingerprintEncoder) decisionRecord(d *DecisionRecord) {
282		e.tag(tagDecisionRecord)
283		if d == nil {
284			return
285		}
286		// OrgRequest fields are written inline at the same nesting depth the
287		// request occupies in the envelope; no field is skipped.
288		e.rawString(d.Request.SubjectOrg)
289		e.rawString(d.Request.ResourceOrg)
290		e.subject(d.Request.Subject)
291		e.resource(d.Request.Resource)
292		e.rawString(d.Request.Action)
293		e.decision(d.Decision)
294	}
295	
296	// encodeCanonical returns the raw bytes fingerprinted for an envelope
297	// whose strings include invalid UTF-8. Every string the record carries
298	// reaches the output byte-for-byte, at whatever nesting depth or list
299	// position it occupies. The prefix separates this encoding space from
300	// JSON fingerprints.
301	func encodeCanonical(env *hashEnvelope) []byte {
302		e := &fingerprintEncoder{buf: []byte(rawEnvelopePrefix)}
303		e.tag(tagEnvelope)
304		e.rawString(env.Org)
305		e.int64Tag(tagSeq, int64(env.Seq))
306		e.rawString(env.Kind)
307		e.change(env.Change)
308		e.decisionRecord(env.Decision)
309		e.rawString(env.PrevFingerprint)
310		return e.buf
311	}
312	
313	// genesisFingerprint derives the chain root from the organization name,
314	// keeping equal identifiers in different organizations independent.
315	func genesisFingerprint(org string) string {
316		sum := sha256.Sum256([]byte("darksafe-audit-genesis\x00" + org))
317		return hex.EncodeToString(sum[:])
318	}
319	
320	// computeFingerprint returns the fingerprint for an envelope. Records made
321	// exclusively of valid UTF-8 keep the historical JSON fingerprint, so old
322	// exports and checkpoints remain valid; records containing invalid bytes
323	// use the length-prefixed raw encoding that protects their exact bytes.
324	func computeFingerprint(env *hashEnvelope) string {
325		if envelopeUsesRawBytes(env) {
326			sum := sha256.Sum256(encodeCanonical(env))
327			return hex.EncodeToString(sum[:])
328		}
329		b, err := json.Marshal(env)
330		if err != nil {
331			// All envelope fields are plain, JSON-encodable values; a failure
332			// here indicates a programming error, not user input.
333			panic(fmt.Errorf("darksafe: audit envelope must encode: %w", err))
334		}
335		sum := sha256.Sum256(b)
336		return hex.EncodeToString(sum[:])
337	}
338	
339	// fingerprintFor builds and fingerprints the envelope for a record.
340	func fingerprintFor(r *AuditRecord) string {
341		return computeFingerprint(&hashEnvelope{
342			Org:             r.Org,
343			Seq:             r.Seq,
344			Kind:            r.Kind,
345			Change:          r.Change,
346			Decision:        r.Decision,
347			PrevFingerprint: r.PrevFingerprint,
348		})
349	}
350	
351	// clonePolicies returns a detached copy of a policy set.
352	func clonePolicies(in []Policy) []Policy {
353		if in == nil {
354			return nil
355		}
356		return append([]Policy(nil), in...)
357	}
358	
359	// cloneChange returns a detached copy of a policy-change payload.
360	func cloneChange(c *PolicyChange) *PolicyChange {
361		if c == nil {
362			return nil
363		}
364		cp := *c
365		cp.Policies = clonePolicies(c.Policies)
366		return &cp
367	}
368	
369	// cloneDecision returns a detached copy of a decision payload.
370	func cloneDecision(d *DecisionRecord) *DecisionRecord {
371		if d == nil {
372			return nil
373		}
374		cp := *d
375		if len(d.Decision.Matched) > 0 {
376			cp.Decision.Matched = append([]string(nil), d.Decision.Matched...)
377		}
378		if len(d.Request.Subject.Roles) > 0 {
379			cp.Request.Subject.Roles = append([]string(nil), d.Request.Subject.Roles...)
380		}
381		return &cp
382	}
383	
384	// cloneRecord returns a fully detached copy of a record.
385	func cloneRecord(r *AuditRecord) *AuditRecord {
386		cp := *r
387		cp.Change = cloneChange(r.Change)
388		cp.Decision = cloneDecision(r.Decision)
389		return &cp
390	}
391	
392	// appendAuditLocked validates, fingerprints and stores one record. It runs
393	// under the store mutex and is the single place records are created.
394	func (st *orgState) appendAuditLocked(org, kind string, change *PolicyChange, decision *DecisionRecord) *AuditRecord {
395		seq := len(st.audit) + 1
396		prev := genesisFingerprint(org)
397		if len(st.audit) > 0 {
398			prev = st.audit[len(st.audit)-1].Fingerprint
399		}
400		// Store detached copies; later caller mutation must not reach the chain.
401		rec := &AuditRecord{
402			Org:             org,
403			Seq:             seq,
404			Kind:            kind,
405			Change:          cloneChange(change),
406			Decision:        cloneDecision(decision),
407			PrevFingerprint: prev,
408		}
409		rec.Fingerprint = fingerprintFor(rec)
410		st.audit = append(st.audit, rec)
411		return cloneRecord(rec)
412	}
413	
414	// auditHeadLocked returns the highest sequence in the chain and the
415	// fingerprint that covers it: (0, genesis) for an organization with no
416	// records.
417	func (st *orgState) auditHeadLocked(org string) (int, string) {
418		if len(st.audit) == 0 {
419			return 0, genesisFingerprint(org)
420		}
421		last := st.audit[len(st.audit)-1]
422		return last.Seq, last.Fingerprint
423	}
424	
425	// Checkpoint pins an audit query to an exact point in a chain.
426	type Checkpoint struct {
427		Org         string
428		EndSeq      int
429		Fingerprint string
430	}
431	
432	// AuditPage is one stable slice of an organization's audit chain.
433	type AuditPage struct {
434		Org     string
435		Records []AuditRecord
436		// BeginSeq/EndSeq delimit the whole pinned range, not just this page.
437		BeginSeq int
438		EndSeq   int
439		// Next is the first sequence of the following page, 0 when exhausted.
440		Next int
441		// Checkpoint is the pinned upper bound shared by every page.
442		Checkpoint Checkpoint
443	}
444	
445	// recordMatches reports whether a record survives the query filters.
446	func recordMatches(r *AuditRecord, kind, subjectID string) bool {
447		if kind != "" && r.Kind != kind {
448			return false
449		}
450		if subjectID != "" {
451			// A subject filter selects decision records of that subject only.
452			if r.Kind != AuditDecision || r.Decision == nil ||
453				r.Decision.Request.Subject.ID != subjectID {
454				return false
455			}
456		}
457		return true
458	}
459	
460	// AuditQuery pins the first page of an audit query. startSeq is the first
461	// sequence considered (1 from the beginning); endSeq <= 0 means "everything
462	// currently stored". The returned checkpoint must be passed to AuditPage
463	// for the following pages, so records appended after the first query never
464	// mix into later pages.
465	func (s *Store) AuditQuery(org string, startSeq, pageSize int, kind, subjectID string) (*AuditPage, error) {
466		if org == "" {
467			return nil, ErrMissingOrganization
468		}
469		if kind != "" && kind != AuditPolicyChange && kind != AuditDecision {
470			return nil, fmt.Errorf("%w: unknown category %q", ErrInvalidPage, kind)
471		}
472		if pageSize <= 0 {
473			return nil, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidPage, pageSize)
474		}
475		if startSeq < 1 {
476			return nil, fmt.Errorf("%w: start sequence must be >= 1, got %d", ErrInvalidPage, startSeq)
477		}
478		s.mu.Lock()
479		defer s.mu.Unlock()
480		st := s.orgLocked(org)
481		end, fingerprint := st.auditHeadLocked(org)
482		cp := Checkpoint{Org: org, EndSeq: end, Fingerprint: fingerprint}
483		if end == 0 {
484			// An organization with no records always yields the empty genesis
485			// page, regardless of where the caller asked to begin.
486			return &AuditPage{Org: org, BeginSeq: 1, EndSeq: 0, Checkpoint: cp}, nil
487		}
488		if startSeq > end {
489			return nil, fmt.Errorf("%w: start sequence %d is beyond end sequence %d", ErrInvalidRange, startSeq, end)
490		}
491		return s.auditPageLocked(org, startSeq, end, fingerprint, pageSize, kind, subjectID), nil
492	}
493	
494	// AuditPage returns one page of a previously pinned query. nextSeq is the
495	// cursor from the previous page; when it is 0 the range is exhausted. The
496	// checkpoint is re-verified against the chain on every call.
497	func (s *Store) AuditPage(cp Checkpoint, nextSeq, pageSize int, kind, subjectID string) (*AuditPage, error) {
498		if cp.Org == "" {
499			return nil, ErrMissingOrganization
500		}
501		if kind != "" && kind != AuditPolicyChange && kind != AuditDecision {
502			return nil, fmt.Errorf("%w: unknown category %q", ErrInvalidPage, kind)
503		}
504		if pageSize <= 0 {
505			return nil, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidPage, pageSize)
506		}
507		if nextSeq < 0 {
508			return nil, fmt.Errorf("%w: next sequence must be >= 0, got %d", ErrInvalidPage, nextSeq)
509		}
510		s.mu.Lock()
511		defer s.mu.Unlock()
512		st, ok := s.orgs[cp.Org]
513		if !ok {
514			// No organization state: the only valid checkpoint is an empty one.
515			g := genesisFingerprint(cp.Org)
516			if cp.EndSeq == 0 && cp.Fingerprint == g && nextSeq == 0 {
517				return &AuditPage{Org: cp.Org, BeginSeq: 0, EndSeq: 0, Checkpoint: cp}, nil
518			}
519			return nil, fmt.Errorf("%w: checkpoint organization has no records", ErrInvalidRange)
520		}
521		head := len(st.audit)
522		if cp.EndSeq < 0 || cp.EndSeq > head {
523			return nil, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, cp.EndSeq, head)
524		}
525		wantFP := genesisFingerprint(cp.Org)
526		if cp.EndSeq > 0 {
527			if cp.EndSeq > len(st.audit) {
528				return nil, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, cp.EndSeq, head)
529			}
530			wantFP = st.audit[cp.EndSeq-1].Fingerprint
531		}
532		if cp.Fingerprint != wantFP {
533			return nil, fmt.Errorf("%w: checkpoint fingerprint does not match the chain at sequence %d", ErrInvalidRange, cp.EndSeq)
534		}
535		if nextSeq == 0 {
536			return &AuditPage{Org: cp.Org, BeginSeq: 1, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
537		}
538		if nextSeq > cp.EndSeq+1 {
539			return nil, fmt.Errorf("%w: next sequence %d beyond pinned range ending at %d", ErrInvalidRange, nextSeq, cp.EndSeq)
540		}
541		if nextSeq == cp.EndSeq+1 {
542			return &AuditPage{Org: cp.Org, BeginSeq: nextSeq, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
543		}
544		return s.auditPageLocked(cp.Org, nextSeq, cp.EndSeq, wantFP, pageSize, kind, subjectID), nil
545	}
546	
547	// auditPageLocked scans forward collecting up to pageSize matching records
548	// and computes the next-page cursor. It does not stop at pageSize raw
549	// records: filtering happens within the pinned [start,end] window.
550	func (s *Store) auditPageLocked(org string, startSeq, endSeq int, endFP string, pageSize int, kind, subjectID string) *AuditPage {
551		st := s.orgs[org]
552		out := make([]AuditRecord, 0, pageSize)
553		i := startSeq
554		for ; i <= endSeq && len(out) < pageSize; i++ {
555			r := st.audit[i-1]
556			if recordMatches(r, kind, subjectID) {
557				out = append(out, *cloneRecord(r))
558			}
559		}
560		next := 0
561		if i <= endSeq {
562			next = i
563		}
564		return &AuditPage{
565			Org:        org,
566			Records:    out,
567			BeginSeq:   startSeq,
568			EndSeq:     endSeq,
569			Next:       next,
570			Checkpoint: Checkpoint{Org: org, EndSeq: endSeq, Fingerprint: endFP},
571		}
572	}
573	
574	// AuditExport returns detached copies of the complete records through
575	// endSeq, suitable for offline verification. endSeq <= 0 means everything
576	// currently stored. An organization with no records yields an empty slice
577	// together with its sequence-0 checkpoint.
578	func (s *Store) AuditExport(org string, endSeq int) (records []AuditRecord, cp Checkpoint, err error) {
579		if org == "" {
580			return nil, Checkpoint{}, ErrMissingOrganization
581		}
582		s.mu.Lock()
583		defer s.mu.Unlock()
584		st := s.orgLocked(org)
585		head := len(st.audit)
586		if endSeq <= 0 {
587			endSeq = head
588		}
589		if endSeq > head {
590			return nil, Checkpoint{}, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, endSeq, head)
591		}
592		if endSeq < 0 {
593			return nil, Checkpoint{}, fmt.Errorf("%w: end sequence must be >= 0, got %d", ErrInvalidPage, endSeq)
594		}
595		// The checkpoint fingerprints the final exported record, not the
596		// possibly later current head.
597		fingerprint := genesisFingerprint(org)
598		if endSeq > 0 {
599			fingerprint = st.audit[endSeq-1].Fingerprint
600		}
601		out := make([]AuditRecord, 0, endSeq)
602		for i := 0; i < endSeq; i++ {
603			out = append(out, *cloneRecord(st.audit[i]))
604		}
605		return out, Checkpoint{Org: org, EndSeq: endSeq, Fingerprint: fingerprint}, nil
606	}
607	
608	// VerifyAudit validates an exported record set entirely without a Store.
609	// The caller separately retains the organization, end sequence and
610	// fingerprint they expect. It rejects any modified field, missing middle or
611	// tail record, swapped order, and record spliced in from another
612	// organization. Empty or nil records validate exactly when the checkpoint
613	// is the organization's genesis (end sequence 0).
614	func VerifyAudit(org string, records []AuditRecord, cp Checkpoint) error {
615		if org == "" {
616			return ErrMissingOrganization
617		}
618		if cp.Org != "" && cp.Org != org {
619			return fmt.Errorf("%w: checkpoint organization %q does not match %q", ErrInvalidRange, cp.Org, org)
620		}
621		genesis := genesisFingerprint(org)
622		if len(records) == 0 {
623			if cp.EndSeq != 0 || cp.Fingerprint != genesis {
624				return fmt.Errorf("%w: empty records but checkpoint claims end sequence %d", ErrInvalidRange, cp.EndSeq)
625			}
626			return nil
627		}
628		if cp.EndSeq != len(records) {
629			return fmt.Errorf("%w: have %d records, checkpoint ends at %d", ErrInvalidRange, len(records), cp.EndSeq)
630		}
631		prev := genesis
632		for i, r := range records {
633			wantSeq := i + 1
634			if r.Org != org {
635				return fmt.Errorf("%w: record %d belongs to organization %q", ErrInvalidRange, wantSeq, r.Org)
636			}
637			if r.Seq != wantSeq {
638				return fmt.Errorf("%w: record %d has sequence %d", ErrInvalidRange, wantSeq, r.Seq)
639			}
640			if r.PrevFingerprint != prev {
641				return fmt.Errorf("%w: record %d breaks the chain", ErrInvalidRange, wantSeq)
642			}
643			wantFP := fingerprintFor(&r)
644			if r.Fingerprint != wantFP {
645				return fmt.Errorf("%w: record %d fingerprint mismatch", ErrInvalidRange, wantSeq)
646			}
647			if r.Kind == AuditPolicyChange {
648				if r.Change == nil || r.Decision != nil {
649					return fmt.Errorf("%w: record %d payload does not match its category", ErrInvalidRange, wantSeq)
650				}
651			} else if r.Kind == AuditDecision {
652				if r.Decision == nil || r.Change != nil {
653					return fmt.Errorf("%w: record %d payload does not match its category", ErrInvalidRange, wantSeq)
654				}
655			} else {
656				return fmt.Errorf("%w: record %d has unknown category %q", ErrInvalidRange, wantSeq, r.Kind)
657			}
658			prev = r.Fingerprint
659		}
660		last := records[len(records)-1]
661		if last.Fingerprint != cp.Fingerprint {
662			return fmt.Errorf("%w: checkpoint fingerprint does not match the final record", ErrInvalidRange)
663		}
664		return nil
665	}
666	
667	// RecheckDecision re-evaluates the request stored in an organization's
668	// decision record against the policy version that decision actually used.
669	// Later publishes or rollbacks cannot alter the result. Non-decision
670	// records and missing sequences return distinguishable errors.
671	func (s *Store) RecheckDecision(org string, seq int) (Decision, error) {
672		if org == "" {
673			return Decision{}, ErrMissingOrganization
674		}
675		if seq < 1 {
676			return Decision{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
677		}
678		s.mu.Lock()
679		defer s.mu.Unlock()
680		st, ok := s.orgs[org]
681		if !ok || seq > len(st.audit) {
682			return Decision{}, fmt.Errorf("%w: organization %q has no audit sequence %d", ErrAuditNotFound, org, seq)
683		}
684		rec := st.audit[seq-1]
685		if rec.Kind != AuditDecision || rec.Decision == nil {
686			return Decision{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
687		}
688		req := rec.Decision.Request
689		version := rec.Decision.Decision.Version
690		if version == 0 {
691			// The original decision evaluated no published version: requests
692			// rejected at the envelope, or an organization with no publish yet.
693			if d, ok := checkRequest(org, req); !ok {
694				return d, nil
695			}
696			return Decision{Allowed: false, Reason: "organization has no published version"}, nil
697		}
698		src, ok := st.versions[version]
699		if !ok {
700			// A decision's version is immutable and never deleted; its absence
701			// indicates store tampering rather than normal operation.
702			return Decision{}, fmt.Errorf("%w: decision used version %d, which no longer exists", ErrVersionNotFound, version)
703		}
704		return evaluate(req, append([]Policy(nil), src...), version), nil
705	}
706

