1	package darksafe
2	
3	import (
4		"errors"
5		"reflect"
6		"sync"
7		"testing"
8	)
9	
10	func allowPolicy(id, subject, action, scope string, recursive bool) Policy {
11		return Policy{ID: id, Subject: subject, Action: action, Scope: scope, Effect: EffectAllow, Recursive: recursive}
12	}
13	
14	func request(org, subjectID, resourceID, scope, action string) OrgRequest {
15		return OrgRequest{
16			SubjectOrg:  org,
17			ResourceOrg: org,
18			Subject:     Subject{ID: subjectID},
19			Resource:    Resource{ID: resourceID, Scope: scope},
20			Action:      action,
21		}
22	}
23	
24	func TestPublishVersionsIncrement(t *testing.T) {
25		s := NewStore()
26		if got := s.CurrentVersion("acme"); got != 0 {
27			t.Fatalf("new org current version = %d, want 0", got)
28		}
29		v, err := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
30		if err != nil || v != 1 {
31			t.Fatalf("first publish = %d, %v; want 1, nil", v, err)
32		}
33		v, err = s.Publish("acme", 1, nil)
34		if err != nil || v != 2 {
35			t.Fatalf("second publish = %d, %v; want 2, nil", v, err)
36		}
37		if got := s.CurrentVersion("acme"); got != 2 {
38			t.Fatalf("current version = %d, want 2", got)
39		}
40	}
41	
42	func TestPublishVersionConflict(t *testing.T) {
43		s := NewStore()
44		if _, err := s.Publish("acme", 0, nil); err != nil {
45			t.Fatal(err)
46		}
47		if _, err := s.Publish("acme", 0, nil); !errors.Is(err, ErrVersionConflict) {
48			t.Fatalf("stale publish err = %v, want ErrVersionConflict", err)
49		}
50		if got := s.CurrentVersion("acme"); got != 1 {
51			t.Fatalf("current version = %d, want 1 after failed publish", got)
52		}
53	}
54	
55	func TestConcurrentPublishSameVersionAtMostOneWins(t *testing.T) {
56		s := NewStore()
57		const n = 16
58		var wg sync.WaitGroup
59		results := make(chan error, n)
60		for i := 0; i < n; i++ {
61			wg.Add(1)
62			go func() {
63				defer wg.Done()
64				_, err := s.Publish("acme", 0, nil)
65				results <- err
66			}()
67		}
68		wg.Wait()
69		close(results)
70		succeeded, conflicts := 0, 0
71		for err := range results {
72			switch {
73			case err == nil:
74				succeeded++
75			case errors.Is(err, ErrVersionConflict):
76				conflicts++
77			default:
78				t.Fatalf("unexpected error %v", err)
79			}
80		}
81		if succeeded != 1 || conflicts != n-1 {
82			t.Fatalf("succeeded=%d conflicts=%d, want 1 and %d", succeeded, conflicts, n-1)
