513	func TestRecheckDecisionReplaysRecordedVersion(t *testing.T) {
514		s := NewStore()
515		v1, _ := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
516		req := request("acme", "u1", "r1", "org/a", "read")
517		original := s.Decide("acme", req) // seq 2, version 1, allowed
518		deniedReq := request("acme", "u2", "r1", "org/a", "read")
519		origDeny := s.Decide("acme", deniedReq) // seq 3, denied by default
520	
521		// Later publish removes the access, then a rollback happens.
522		s.Publish("acme", 1, nil)
523		s.Rollback("acme", 2, 1)
524		// Current version is 3. A fresh decide for u2 would still deny; u1 allowed.
525		// Rechecking seq 2 must reproduce the version-1 allow.
526		got, err := s.RecheckDecision("acme", 2)
527		if err != nil {
528			t.Fatal(err)
529		}
530		if !reflect.DeepEqual(got, original) || got.Version != v1 {
531			t.Fatalf("recheck = %+v, want original %+v (version %d)", got, original, v1)
532		}
533		gotDeny, err := s.RecheckDecision("acme", 3)
534		if err != nil || !reflect.DeepEqual(gotDeny, origDeny) {
535			t.Fatalf("recheck deny = %+v, %v, want %+v", gotDeny, err, origDeny)
536		}
537	
538		// A no-published-version denial rechecks as the same denial.
539		s.Decide("blank", request("blank", "u1", "r1", "org/a", "read"))
540		if d, err := s.RecheckDecision("blank", 1); err != nil || d.Allowed ||
541			d.Reason != "organization has no published version" {
542			t.Fatalf("recheck no-version denial = %+v, %v", d, err)
543		}
544		// An envelope rejection rechecks through the same envelope checks.
545		mismatch := request("acme", "u1", "r1", "org/a", "read")
546		mismatch.SubjectOrg = "globex"
547		s.Decide("acme", mismatch) // publish=seq1, decides=2,3,6; publish=4; rollback=5
548		if d, err := s.RecheckDecision("acme", 6); err != nil || d.Allowed || d.Reason != "organization mismatch" {
549			t.Fatalf("recheck mismatch = %+v, %v", d, err)
550		}
551	
552		// Distinguishable errors.
553		if _, err := s.RecheckDecision("acme", 1); !errors.Is(err, ErrAuditNotADecision) {
554			t.Fatalf("recheck policy_change err = %v", err)
555		}
556		if _, err := s.RecheckDecision("acme", 99); !errors.Is(err, ErrAuditNotFound) {
557			t.Fatalf("recheck missing seq err = %v", err)
558		}
559		if _, err := s.RecheckDecision("ghost", 1); !errors.Is(err, ErrAuditNotFound) {
560			t.Fatalf("recheck unknown org err = %v", err)
561		}
562	}
