75	// TestInvalidUTF8IsAcceptedAndPreservedByteForByte drives the live API
76	// with strings carrying invalid UTF-8 in every policy and request string
77	// reachable through the public surface. Acceptance must be unchanged, no
78	// byte may be deleted, replaced or normalized, and query/export/offline
79	// review must observe the exact submitted bytes.
80	func TestInvalidUTF8IsAcceptedAndPreservedByteForByte(t *testing.T) {
81		s := NewStore()
82		submitted := Policy{
83			ID:      "策" + invalidByte + "略",
84			Subject: "用" + invalidByte + "戶",
85			Action:  "读" + invalidByte,
86			Scope:   "org/a/资" + invalidByte + "料",
87			Effect:  EffectAllow,
88		}
89		v, err := s.Publish("acme", 0, []Policy{submitted})
90		if err != nil || v != 1 {
91			t.Fatalf("publish with invalid UTF-8 = %d, %v; want accepted", v, err)
92		}
93	
94		req := OrgRequest{
95			SubjectOrg:  "acme",
96			ResourceOrg: "acme",
97			Subject: Subject{
98				ID:    "用" + invalidByte + "戶",
99				Kind:  "外" + invalidByte + "部",
100				Roles: []string{"角" + invalidByte + "色", "普通角色"},
101			},
102			Resource: Resource{ID: "资" + invalidByte + "源", Scope: submitted.Scope},
103			Action:   submitted.Action,
104		}
105		d := s.Decide("acme", req)
106		if !d.Allowed || d.Version != 1 || d.Reason != "matched allow policy" {
107			t.Fatalf("decision on invalid-UTF-8 request = %+v", d)
108		}
109		if want := []string{submitted.ID}; !reflect.DeepEqual(d.Matched, want) {
110			t.Fatalf("matched = %q, want byte-exact %q", d.Matched, want)
111		}
112		if !strings.Contains(d.Matched[0], invalidByte) {
113			t.Fatal("invalid byte normalized out of matched policy id")
114		}
115	
116		// A rollback republishes the invalid-byte content and records it.
117		if rv, err := s.Rollback("acme", 1, 1); err != nil || rv != 2 {
118			t.Fatalf("rollback = %d, %v", rv, err)
119		}
120		// A normal record and an invalid-byte record coexist in one export.
121		if _, err := s.Publish("acme", 2, nil); err != nil {
122			t.Fatal(err)
123		}
124		plain := s.Decide("acme", request("acme", "plain", "r1", "org/a", "read"))
125		if plain.Allowed {
126			t.Fatalf("plain request under empty version must deny: %+v", plain)
127		}
128	
129		recs, cp, err := s.AuditExport("acme", 0)
130		if err != nil {
131			t.Fatal(err)
132		}
133		if err := VerifyAudit("acme", recs, cp); err != nil {
134			t.Fatalf("export with invalid UTF-8 must verify: %v", err)
135		}
136	
137		// The export is byte-for-byte the submitted content at every level.
138		gotPolicy := recs[0].Change.Policies[0]
139		if !reflect.DeepEqual(gotPolicy, submitted) {
140			t.Fatalf("policy bytes = %+v, want %+v", gotPolicy, submitted)
141		}
142		gotReq := recs[1].Decision.Request
143		if !reflect.DeepEqual(gotReq, req) {
144			t.Fatalf("request bytes = %+v, want %+v", gotReq, req)
145		}
146		if !reflect.DeepEqual(recs[1].Decision.Decision, d) {
147			t.Fatalf("decision bytes = %+v, want %+v", recs[1].Decision.Decision, d)
148		}
149		if !reflect.DeepEqual(recs[2].Change.Policies, []Policy{submitted}) {
150			t.Fatal("rollback record lost the published raw bytes")
151		}
152		for _, haystack := range []string{
153			gotPolicy.ID, gotPolicy.Subject, gotPolicy.Action, gotPolicy.Scope,
154			gotReq.Subject.ID, gotReq.Subject.Kind, gotReq.Subject.Roles[0],
155			gotReq.Resource.ID, gotReq.Resource.Scope, gotReq.Action,
156		} {
157			if !strings.Contains(haystack, invalidByte) {
158				t.Fatalf("invalid byte was deleted or normalized in %q", haystack)
159			}
160		}
161	
162		// Paged queries return the same bytes.
163		page, err := s.AuditQuery("acme", 1, 1, "", "")
164		if err != nil {
165			t.Fatal(err)
166		}
167		queried := append([]AuditRecord(nil), page.Records...)
168		for page.Next != 0 {
169			page, err = s.AuditPage(page.Checkpoint, page.Next, 1, "", "")
170			if err != nil {
171				t.Fatal(err)
172			}
173			queried = append(queried, page.Records...)
174		}
175		if !reflect.DeepEqual(queried, recs) {
176			t.Fatal("paged query bytes differ from the export bytes")
177		}
178	
179		// Offline review recomputes from the raw request and recorded version.
180		review, err := RecheckDecisionOffline("acme", recs, cp, 2)
181		if err != nil {
182			t.Fatalf("offline review: %v", err)
183		}
184		if !review.Consistent || !reflect.DeepEqual(review.Original, d) ||
185			!reflect.DeepEqual(review.Recomputed, d) {
186			t.Fatalf("offline review = %+v, want consistent with %+v", review, d)
187		}
188		if !strings.Contains(review.Recomputed.Matched[0], invalidByte) {
189			t.Fatal("offline review normalized the matched policy id")
190		}
191	
192		// An organization whose name itself carries invalid bytes: genesis
193		// checkpoint, isolation and offline review all still work.
194		weirdOrg := "组" + invalidByte + "织"
195		if _, err := s.Publish(weirdOrg, 0, []Policy{submitted}); err != nil {
196			t.Fatalf("publish into invalid-UTF-8 org: %v", err)
197		}
198		wreq := req
199		wreq.SubjectOrg = weirdOrg
200		wreq.ResourceOrg = weirdOrg
201		if d := s.Decide(weirdOrg, wreq); !d.Allowed {
202			t.Fatalf("decision inside invalid-UTF-8 org = %+v", d)
203		}
204		wrecs, wcp, err := s.AuditExport(weirdOrg, 0)
205		if err != nil {
206			t.Fatal(err)
207		}
208		if err := VerifyAudit(weirdOrg, wrecs, wcp); err != nil {
209			t.Fatalf("invalid-UTF-8 org chain: %v", err)
210		}
211		if wr, err := RecheckDecisionOffline(weirdOrg, wrecs, wcp, 2); err != nil || !wr.Consistent {
212			t.Fatalf("invalid-UTF-8 org offline review = %+v, %v", wr, err)
213		}
214		// The sequence-0 root checkpoint is the genesis for that org too.
215		empty, emptyCP, err := s.AuditExport(weirdOrg+"-none", 0)
216		if err != nil {
217			t.Fatal(err)
218		}
219		if err := VerifyAudit(weirdOrg+"-none", empty, emptyCP); err != nil {
220			t.Fatalf("genesis checkpoint: %v", err)
221		}
222	}
