230		s := NewStore()
231		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
232		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
233		s.Publish("acme", 1, []Policy{{
234			ID:      "策" + invalidByte + "略",
235			Subject: "用" + invalidByte + "戶",
236			Action:  "read",
237			Scope:   "org/a",
238			Effect:  EffectAllow,
239		}})
240		recs, cp, err := s.AuditExport("acme", 0)
241		if err != nil {
