248			t.Fatal("valid-UTF-8 record changed fingerprint family")
249		}
250		if got := fingerprintFor(&recs[1]); got != legacyJSONFingerprint(&recs[1]) {
251			t.Fatal("valid-UTF-8 decision changed fingerprint family")
252		}
