463	// TestReplacementRuneIsGenuineContentToo separates three byte-different
464	// strings that displays may conflate: a lone 0xFF, a lone 0xFE, and a
465	// real U+FFFD rune. A record genuinely containing U+FFFD is valid UTF-8,
466	// verifies and keeps the legacy fingerprint; substituting any one for
467	// another is a content change.
468	func TestReplacementRuneIsGenuineContentToo(t *testing.T) {
469		s := NewStore()
470		policies := []Policy{{
471			ID:      "p-" + replacementRune + "-1",
472			Subject: "用" + replacementRune + "戶",
473			Action:  "read", Scope: "org/a", Effect: EffectAllow,
474		}}
475		s.Publish("acme", 0, policies)
476		req := request("acme", "用"+replacementRune+"戶", "r1", "org/a", "read")
477		d := s.Decide("acme", req)
478		if !d.Allowed {
479			t.Fatalf("request with genuine U+FFFD = %+v", d)
480		}
481		recs, cp, err := s.AuditExport("acme", 0)
482		if err != nil {
483			t.Fatal(err)
484		}
485		if err := VerifyAudit("acme", recs, cp); err != nil {
486			t.Fatalf("genuine U+FFFD must verify: %v", err)
487		}
488		if !utf8.ValidString(recs[0].Change.Policies[0].ID) {
489			t.Fatal("genuine U+FFFD must remain valid UTF-8")
490		}
491		if fingerprintFor(&recs[0]) != legacyJSONFingerprint(&recs[0]) {
492			t.Fatal("valid-UTF-8 U+FFFD record must keep the legacy JSON fingerprint")
493		}
494		if review, err := RecheckDecisionOffline("acme", recs, cp, 2); err != nil || !review.Consistent {
495			t.Fatalf("genuine U+FFFD review = %+v, %v", review, err)
496		}
497	
498		// Raw invalid bytes exported from the live API.
499		raw := NewStore()
500		raw.Publish("acme", 0, []Policy{{
501			ID: "p" + invalidByte, Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow,
502		}})
503		rawRecs, rawCP, err := raw.AuditExport("acme", 0)
504		if err != nil {
505			t.Fatal(err)
506		}
507		if err := VerifyAudit("acme", rawRecs, rawCP); err != nil {
508			t.Fatalf("raw-byte record must verify: %v", err)
509		}
510	
511		// Replace the raw byte with a genuine U+FFFD rune: content changed.
512		tampered := cloneExportedRecords(rawRecs)
513		tampered[0].Change.Policies[0].ID = "p" + replacementRune
514		if err := VerifyAudit("acme", tampered, rawCP); !errors.Is(err, ErrInvalidRange) {
515			t.Fatalf("raw 0xFF -> U+FFFD err = %v, want ErrInvalidRange", err)
516		}
517	
518		// The reverse substitution is also a change: the valid-UTF-8 record's
519		// real U+FFFD replaced by a lone 0xFF.
520		back := cloneExportedRecords(recs)
521		back[0].Change.Policies[0].ID = "p-" + invalidByte + "-1"
522		if err := VerifyAudit("acme", back, cp); !errors.Is(err, ErrInvalidRange) {
523			t.Fatalf("U+FFFD -> raw 0xFF err = %v, want ErrInvalidRange", err)
524		}
525	}
