403				func(seq int) (string, *PolicyChange, *DecisionRecord) {
404					return AuditPolicyChange, &PolicyChange{Version: 1, Policies: nil}, nil
405				},
406				func(seq int) (string, *PolicyChange, *DecisionRecord) {
407					return AuditDecision, nil, &DecisionRecord{
408						Request:  req,
409						Decision: Decision{Allowed: false, Reason: "no matching allow policy", Matched: matched, Version: 1},
410					}
411				},
412			})
413		}
414		for _, matched := range [][]string{nil, {}} {
415			recs, cp := build(matched)
416			got, err := RecheckDecisionOffline("acme", recs, cp, 2)
417			if err != nil {
418				t.Fatalf("matched=%v: %v", matched, err)
419			}
420			if !got.Consistent {
421				t.Fatalf("nil and empty matched lists must agree: original=%+v recomputed=%+v",
422					got.Original, got.Recomputed)
423			}
424		}
425	}
426	
427	func TestOfflineReviewIsReadOnlyAndDetached(t *testing.T) {
428		s := NewStore()
429		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
